WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_d_multi_people'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多人年龄差应用', 'kp-age-d-multi-people', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多人年龄差序列"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "甲比乙大 2 岁，乙比丙大 2 岁……这构成了等差数列！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“家里有四个孩子，相邻的两个孩子年龄都相差 2 岁。四个孩子总年龄 48 岁。”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "利用等差数列求和公式："}]}, {"type": "katexBlock", "attrs": {"content": "\\text{总年龄} = \\text{中间项(或平均年龄)} \\times \\text{人数}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[确认人数 n 和恒定年龄差 d] --> B[确认总年龄 Sum]\nB --> C[用 Sum / n 算出平均年龄(中位数)]\nC --> D[如果是奇数个人, 中位数就是正中间那个人的年龄]\nD --> E[如果是偶数个人, 中位数卡在中间两人之间, 分别加减 d/2 求出具体年龄]"}}]}$$ AS jsonb), NULL, '多人年龄差应用的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "多人年龄差应用"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_d_multi_people", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
